// ================================================================
// Calcula as métricas da semana anterior (segunda a sexta) e as
// compara com a semana retrasada, a partir dos dados brutos das
// 4 planilhas. Roda toda segunda às 8h (gatilho).
// ================================================================

function parseDataBR(str) {
  if (!str) return null;
  const partes = String(str).trim().split(' ');
  const [d, m, y] = partes[0].split('/').map(Number);
  if (!d || !m || !y) return null;
  let hh = 0, mi = 0, ss = 0;
  if (partes[1]) {
    const t = partes[1].split(':').map(Number);
    hh = t[0] || 0; mi = t[1] || 0; ss = t[2] || 0;
  }
  return new Date(y, m - 1, d, hh, mi, ss);
}

function dentro(data, inicio, fim) {
  return data !== null && data >= inicio && data <= fim;
}

function fmt(atual, anterior) {
  if (atual === anterior) {
    return anterior ? `${atual} = semana passada (${anterior})` : `${atual} = semana passada`;
  }
  if (anterior === 0) return `${atual} (novo — 0 na semana passada)`;
  const pct = ((atual - anterior) / anterior) * 100;
  const sinal = pct >= 0 ? '+' : '-';
  return `${atual} ${sinal}${Math.abs(pct).toFixed(0)}% em relação à semana passada (${anterior})`;
}

function fmtTaxa(atualPct, anteriorPct) {
  const diff = atualPct - anteriorPct;
  if (diff === 0) return `${atualPct}% = semana passada (${anteriorPct}%)`;
  const sinal = diff >= 0 ? '+' : '';
  return `${atualPct}% ${sinal}${diff}% em relação à semana passada (${anteriorPct}%)`;
}

// ---------- Definição da semana (segunda a sexta) ----------
// O gatilho roda na segunda às 8h; a "semana atual" do relatório é a
// que acabou de terminar (segunda a sexta passados).
const hoje = new Date();
const semanaFim = new Date(hoje); semanaFim.setDate(hoje.getDate() - 3); semanaFim.setHours(23, 59, 59, 999);
const semanaInicio = new Date(semanaFim); semanaInicio.setDate(semanaFim.getDate() - 4); semanaInicio.setHours(0, 0, 0, 0);
const semanaAntFim = new Date(semanaInicio); semanaAntFim.setDate(semanaInicio.getDate() - 3); semanaAntFim.setHours(23, 59, 59, 999);
const semanaAntInicio = new Date(semanaAntFim); semanaAntInicio.setDate(semanaAntFim.getDate() - 4); semanaAntInicio.setHours(0, 0, 0, 0);

// ---------- Dados brutos das 4 planilhas ----------
const ligacoes = $('Ler Ligações').all().map(i => i.json);
const reunioes = $('Ler Reuniões').all().map(i => i.json);
const inbound  = $('Ler Inbound').all().map(i => i.json);
const outbound = $('Ler Outbound').all().map(i => i.json);

const RESPONSAVEIS = ['CAMILA', 'ALISSON'];

// ---------- LIGAÇÕES (só Camila + Alisson) ----------
const ligFiltradas = ligacoes.filter(l => RESPONSAVEIS.includes((l['Usuário'] || '').trim().toUpperCase()));
const ligA = ligFiltradas.filter(l => dentro(parseDataBR(l['Data / Hora']), semanaInicio, semanaFim));
const ligP = ligFiltradas.filter(l => dentro(parseDataBR(l['Data / Hora']), semanaAntInicio, semanaAntFim));

const totA = ligA.length, totP = ligP.length;
const atendA = ligA.filter(l => l['Atendida'] === 'Sim').length;
const atendP = ligP.filter(l => l['Atendida'] === 'Sim').length;
const taxaA = totA ? Math.round((atendA / totA) * 100) : 0;
const taxaP = totP ? Math.round((atendP / totP) * 100) : 0;

const porPessoa = {};
for (const pessoa of RESPONSAVEIS) {
  const subA = ligA.filter(l => (l['Usuário'] || '').trim().toUpperCase() === pessoa);
  const subP = ligP.filter(l => (l['Usuário'] || '').trim().toUpperCase() === pessoa);
  const atA = subA.filter(l => l['Atendida'] === 'Sim').length;
  const atP = subP.filter(l => l['Atendida'] === 'Sim').length;
  const txA = subA.length ? Math.round((atA / subA.length) * 100) : 0;
  const txP = subP.length ? Math.round((atP / subP.length) * 100) : 0;
  porPessoa[pessoa] = { totalA: subA.length, totalP: subP.length, atA, atP, txA, txP };
}

// ---------- REUNIÕES ----------
const status = r => (r['STATUS'] || '').trim();
const reuA = reunioes.filter(r => dentro(parseDataBR(r['AGENDAMENTO']), semanaInicio, semanaFim));
const reuP = reunioes.filter(r => dentro(parseDataBR(r['AGENDAMENTO']), semanaAntInicio, semanaAntFim));
const agA = reuA.length, agP = reuP.length;
const realA = reuA.filter(r => status(r) === 'Realizada').length;
const realP = reuP.filter(r => status(r) === 'Realizada').length;
const noshowA = reuA.filter(r => status(r) === 'Lead não compareceu').length;
const noshowP = reuP.filter(r => status(r) === 'Lead não compareceu').length;
const cancelA = reuA.filter(r => ['Cancelado p/ lead', 'Cancelado p/ MS'].includes(status(r))).length;
const cancelP = reuP.filter(r => ['Cancelado p/ lead', 'Cancelado p/ MS'].includes(status(r))).length;

// ---------- INBOUND ----------
const ibNovosA = inbound.filter(l => dentro(parseDataBR(l['Data de entrada']), semanaInicio, semanaFim));
const ibNovosP = inbound.filter(l => dentro(parseDataBR(l['Data de entrada']), semanaAntInicio, semanaAntFim));
function validosInvalidos(lista) {
  const invalidos = lista.filter(l => (l['Cadencia Inbound'] || '').trim() === 'Lead Inválido').length;
  return { validos: lista.length - invalidos, invalidos };
}
const viA = validosInvalidos(ibNovosA), viP = validosInvalidos(ibNovosP);
const ibReuniaoA = inbound.filter(l => dentro(parseDataBR(l['Reunião de apresentação']), semanaInicio, semanaFim));
const ibReuniaoP = inbound.filter(l => dentro(parseDataBR(l['Reunião de apresentação']), semanaAntInicio, semanaAntFim));

// ---------- OUTBOUND ----------
const obContatosA = outbound.filter(l => dentro(parseDataBR(l['Data da ligação contato inicial']), semanaInicio, semanaFim));
const obContatosP = outbound.filter(l => dentro(parseDataBR(l['Data da ligação contato inicial']), semanaAntInicio, semanaAntFim));
const obReuniaoA = outbound.filter(l => dentro(parseDataBR(l['Reunião comercial OB']), semanaInicio, semanaFim));
const obReuniaoP = outbound.filter(l => dentro(parseDataBR(l['Reunião comercial OB']), semanaAntInicio, semanaAntFim));

// ---------- INSIGHTS (regra: variação >= 20% em módulo, sem LLM) ----------
const insights = [];
function registrarInsight(nome, atual, anterior, invertido) {
  if (!anterior) return;
  const pct = ((atual - anterior) / anterior) * 100;
  if (Math.abs(pct) < 20) return;
  const caiu = pct < 0;
  const ruim = invertido ? !caiu : caiu;
  const emoji = ruim ? '⚠️' : '✅';
  insights.push(`${emoji} ${nome} ${caiu ? 'caiu' : 'subiu'} ${Math.abs(pct).toFixed(0)}% em relação à semana passada.`);
}
registrarInsight('Volume de ligações', totA, totP);
registrarInsight('Taxa de atendimento', taxaA, taxaP);
registrarInsight('Agendamentos de reunião', agA, agP);
registrarInsight('No-show', noshowA, noshowP, true);
registrarInsight('Novos leads Inbound', ibNovosA.length, ibNovosP.length);
registrarInsight('Contatos iniciais Outbound', obContatosA.length, obContatosP.length);

// ---------- MONTAGEM DO TEXTO DO E-MAIL ----------
const fmtData = d => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`;
const assunto = `Relatório semanal dashboard - ${fmtData(semanaInicio)} até ${fmtData(semanaFim)}`;

const linhas = [];
linhas.push('Bom dia, time! Segue o relatório semanal do dashboard.\n');
linhas.push('LIGAÇÕES (Camila + Alisson)');
linhas.push(`Total de ligações: ${fmt(totA, totP)}`);
linhas.push(`Atendidas: ${fmt(atendA, atendP)}`);
linhas.push(`Taxa de atendimento: ${fmtTaxa(taxaA, taxaP)}`);
for (const pessoa of RESPONSAVEIS) {
  const p = porPessoa[pessoa];
  const nome = pessoa.charAt(0) + pessoa.slice(1).toLowerCase();
  linhas.push(`\n  ${nome}:`);
  linhas.push(`  Ligações: ${fmt(p.totalA, p.totalP)}`);
  linhas.push(`  Atendidas: ${fmt(p.atA, p.atP)}`);
  linhas.push(`  Taxa de atendimento: ${fmtTaxa(p.txA, p.txP)}`);
}
linhas.push('\nREUNIÕES');
linhas.push(`Agendamentos: ${fmt(agA, agP)}`);
linhas.push(`Realizadas: ${fmt(realA, realP)}`);
linhas.push(`No-show: ${fmt(noshowA, noshowP)}`);
linhas.push(`Canceladas: ${fmt(cancelA, cancelP)}`);
linhas.push('\nINBOUND');
linhas.push(`Novos leads: ${fmt(ibNovosA.length, ibNovosP.length)}`);
linhas.push(`  Válidos: ${fmt(viA.validos, viP.validos)}`);
linhas.push(`  Inválidos: ${fmt(viA.invalidos, viP.invalidos)}`);
linhas.push(`Reuniões marcadas: ${fmt(ibReuniaoA.length, ibReuniaoP.length)}`);
linhas.push('\nOUTBOUND');
linhas.push(`Contatos iniciais realizados: ${fmt(obContatosA.length, obContatosP.length)}`);
linhas.push(`Reuniões marcadas: ${fmt(obReuniaoA.length, obReuniaoP.length)}`);
linhas.push('\nINSIGHTS');
linhas.push(insights.length ? insights.join('\n') : 'Nenhuma variação relevante (acima de 20%) identificada essa semana.');

const corpo = linhas.join('\n');

return [{
  json: {
    assunto,
    corpo,
    semana_inicio: fmtData(semanaInicio),
    semana_fim: fmtData(semanaFim),
    ligacoes_total: totA,
    ligacoes_atendidas: atendA,
    ligacoes_taxa: taxaA,
    camila_ligacoes: porPessoa['CAMILA'].totalA,
    camila_atendidas: porPessoa['CAMILA'].atA,
    camila_taxa: porPessoa['CAMILA'].txA,
    alisson_ligacoes: porPessoa['ALISSON'].totalA,
    alisson_atendidas: porPessoa['ALISSON'].atA,
    alisson_taxa: porPessoa['ALISSON'].txA,
    reunioes_agendamentos: agA,
    reunioes_realizadas: realA,
    reunioes_noshow: noshowA,
    reunioes_canceladas: cancelA,
    ib_novos_leads: ibNovosA.length,
    ib_validos: viA.validos,
    ib_invalidos: viA.invalidos,
    ib_reunioes_marcadas: ibReuniaoA.length,
    ob_contatos_iniciais: obContatosA.length,
    ob_reunioes_marcadas: obReuniaoA.length,
  }
}];
